const query = $input.first().json.query || {}

// =========================
// DEFAULTS
// =========================
const now = new Date()
const defaultTo = now
const defaultFrom = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000)

// =========================
// SAFE DATE FORMATTER
// =========================
function formatDate(date) {
  return date.toISOString().split("T")[0]
}

// =========================
// PARSE INPUT DATES
// =========================
function parseDate(input, fallback) {
  if (!input) return fallback
  const d = new Date(input)
  if (isNaN(d.getTime())) return fallback
  return d
}

const fromDate = parseDate(query.from, defaultFrom)
const toDate = parseDate(query.to, defaultTo)

// =========================
// NORMALIZED OUTPUT
// =========================
const from = formatDate(fromDate)
const to = formatDate(toDate)

// =========================
// OTHER FILTERS
// =========================
const branch = query.branch && query.branch !== "all" ? query.branch : null
const batch = query.batch && query.batch !== "all" ? query.batch : null
const category = query.category || null
const lowStockOnly = query.lowStockOnly === "true"

// Pagination
const page = parseInt(query.page || "1", 10)
const limit = parseInt(query.limit || "20", 10)
const offset = (page - 1) * limit

return [{
  json: {
    from,
    to,
    fromDate: fromDate.toISOString(),
    toDate: toDate.toISOString(),
    branch,
    batch,
    category,
    lowStockOnly,
    page,
    limit,
    offset
  }
}]

const params = $input.first().json

// Mock inventory data - Replace with actual database query
// In production, you would query your inventory database here

const allProducts = [
  { id: 'P001', name: 'Premium Coffee Beans', category: 'Beverages', quantity: 234, minStock: 100, maxStock: 500, costPrice: 50, sellingPrice: 75 },
  { id: 'P002', name: 'Organic Green Tea', category: 'Beverages', quantity: 189, minStock: 80, maxStock: 400, costPrice: 45, sellingPrice: 68 },
  { id: 'P003', name: 'Espresso Machine', category: 'Equipment', quantity: 45, minStock: 20, maxStock: 100, costPrice: 300, sellingPrice: 499 },
  { id: 'P004', name: 'Coffee Filters', category: 'Accessories', quantity: 567, minStock: 200, maxStock: 1000, costPrice: 5, sellingPrice: 12 },
  { id: 'P005', name: 'Milk Frother', category: 'Equipment', quantity: 78, minStock: 30, maxStock: 150, costPrice: 45, sellingPrice: 89 },
  { id: 'P006', name: 'Coffee Mugs', category: 'Accessories', quantity: 345, minStock: 150, maxStock: 600, costPrice: 8, sellingPrice: 19 },
  { id: 'P007', name: 'Syrup Variety Pack', category: 'Beverages', quantity: 123, minStock: 50, maxStock: 300, costPrice: 25, sellingPrice: 45 },
  { id: 'P008', name: 'Coffee Grinder', category: 'Equipment', quantity: 23, minStock: 15, maxStock: 80, costPrice: 120, sellingPrice: 199 },
  { id: 'P009', name: 'Travel Tumbler', category: 'Accessories', quantity: 456, minStock: 100, maxStock: 800, costPrice: 12, sellingPrice: 29 },
  { id: 'P010', name: 'Cold Brew Kit', category: 'Equipment', quantity: 12, minStock: 10, maxStock: 50, costPrice: 35, sellingPrice: 59 }
]

// Apply filters
let filteredProducts = [...allProducts]

if (params.branch) {
  // Different branches have different inventory levels
  const branchMultiplier = {
    'branch_1': 1.2,
    'branch_2': 0.8,
    'branch_3': 1.0
  }
  const multiplier = branchMultiplier[params.branch] || 1
  filteredProducts = filteredProducts.map(p => ({
    ...p,
    quantity: Math.floor(p.quantity * multiplier),
    minStock: Math.floor(p.minStock * multiplier),
    maxStock: Math.floor(p.maxStock * multiplier)
  }))
}

if (params.category) {
  filteredProducts = filteredProducts.filter(p => p.category === params.category)
}

if (params.lowStockOnly) {
  filteredProducts = filteredProducts.filter(p => p.quantity <= p.minStock)
}

// Calculate low stock and out of stock
const lowStockItems = filteredProducts.filter(p => p.quantity > 0 && p.quantity <= p.minStock).length
const outOfStockItems = filteredProducts.filter(p => p.quantity === 0).length
const reorderNeeded = filteredProducts.filter(p => p.quantity < p.minStock * 0.7).length

// Calculate total inventory value (using selling price)
const totalValue = filteredProducts.reduce((sum, p) => sum + (p.quantity * p.sellingPrice), 0)

// Get top products by value
const topProducts = filteredProducts
  .map(p => ({
    id: p.id,
    name: p.name,
    quantity: p.quantity,
    value: p.quantity * p.sellingPrice,
    unitPrice: p.sellingPrice
  }))
  .sort((a, b) => b.value - a.value)
  .slice(0, 10)

// Get categories summary
const categoriesMap = filteredProducts.reduce((acc, p) => {
  if (!acc[p.category]) {
    acc[p.category] = { count: 0, value: 0, items: [] }
  }
  acc[p.category].count += p.quantity
  acc[p.category].value += p.quantity * p.sellingPrice
  acc[p.category].items.push(p.name)
  return acc
}, {})

const categories = Object.keys(categoriesMap).map(name => ({
  name,
  count: categoriesMap[name].count,
  value: categoriesMap[name].value,
  percentageOfTotal: (categoriesMap[name].value / totalValue) * 100
}))

// Pagination
const paginatedProducts = topProducts.slice(params.offset, params.offset + params.limit)

return [{
  json: {
    totalProducts: filteredProducts.length,
    lowStockItems,
    outOfStockItems,
    totalValue,
    reorderNeeded,
    topProducts: paginatedProducts,
    categories,
    allProducts: filteredProducts,
    filters: params
  }
}]
